mapper.select:
SELECT slug FROM problem WHERE slug IN
#{slug}
ORDER BY slug ASC

mapper.delete:
DELETE FROM problem_relation relation
USING problem source_problem
WHERE relation.source_problem_id = source_problem.id
  AND source_problem.slug = #{problemSlug}
  AND relation.source = #{source}

DELETE FROM problem_hint hint
USING problem source_problem
WHERE hint.problem_id = source_problem.id
  AND source_problem.slug = #{problemSlug}
  AND hint.source_site = #{sourceSite}

DELETE FROM problem_category_item item
USING problem source_problem
WHERE item.problem_id = source_problem.id
  AND source_problem.slug = #{problemSlug}
  AND item.source = #{source}

mapper.insert:
INSERT INTO problem_category_item (
  category_id, problem_id, source, source_snapshot, created_at
)
SELECT category.id, problem.id, #{source}, #{sourceSnapshot}, NOW()
FROM problem_category category
JOIN problem ON problem.slug = #{problemSlug}
WHERE category.slug = #{categorySlug}
ON CONFLICT (category_id, problem_id, source) DO UPDATE
SET source_snapshot = EXCLUDED.source_snapshot
WHERE problem_category_item.source_snapshot IS DISTINCT FROM EXCLUDED.source_snapshot
